-- Cupo (eventos rápidos con registro, cover y QR; segunda app de Diversificación, en os.vorka.mx/cupo/).
-- Los eventos gratis no pasan por la tienda. Aquí se vende Cupo Pro como producto de ACCESO (contenido.acceso.app = 'cupo'):
-- el correo de compra lleva a os.vorka.mx/cupo/entrar/<token> y os.vorka.mx convierte cada unidad en un evento Pro (ver vorka-os/PLAN-CUPO.md).
-- Entran a la venta de inmediato (temporada de Halloween). Se pausan o cambian de precio desde Vorka México → Tienda → Productos.
INSERT OR IGNORE INTO products (id, slug, nombre, descripcion_corta, precio_centavos, activo, categoria, orden, r2_keys, imagen, contenido) VALUES
('prod_cupo_pro', 'cupo-pro', 'Cupo Pro · un evento', 'Cobra cover en tu evento (transferencia, liga de pago o en la puerta), aprueba registros y recibe hasta 1,000 personas. Sin comisión por boleto.', 19900, 1, 'Eventos', 30, '[]', '/assets/tienda/cupo.webp',
  json('{"acceso":{"app":"cupo","tipo":"pro","url":"https://os.vorka.mx/cupo/entrar/","boton":"Entrar a Cupo","detalle":"Pago único · un evento Pro"},"titular":"Tu evento con cover, sin comisiones","subtitulo":"Página del evento, registro sin cuentas, cover pagado directo a ti, recordatorios automáticos y check-in con QR. Pago único por evento.","incluye":[{"titulo":"Cobro de cover","texto":"Tu CLABE con botón de copiar, tu liga de pago o pago en la puerta. El dinero llega directo a ti."},{"titulo":"Confirmas pagos con un toque","texto":"La persona avisa que pagó y tú tocas “Pagado”: le llega su entrada con QR."},{"titulo":"Hasta 1,000 personas","texto":"Con lista de espera automática cuando se llena."},{"titulo":"Aprobar registros y preguntas","texto":"Revisa quién entra y pide datos como empresa o talla."},{"titulo":"10 avisos a tus asistentes","texto":"Además de los recordatorios automáticos un día y dos horas antes."},{"titulo":"Check-in con tu equipo","texto":"Una liga para que escaneen desde su celular, sin cuenta, y lista en Excel."}],"para_quien":["Fiestas y eventos de Halloween con cover","Networking, talleres y eventos de negocio","Comunidades y organizadores que cobran entrada"],"faq":[{"p":"¿Cupo cobra comisión por mi cover?","r":"No. Las personas te pagan directo a ti y tú confirmas cada pago. Solo pagas Cupo Pro una vez por evento."},{"p":"¿Necesito Pro para eventos gratis?","r":"No. Los eventos gratis de hasta 100 personas no cuestan nada en <a href=\"https://os.vorka.mx/cupo/\">os.vorka.mx/cupo</a>."},{"p":"¿Cómo lo uso después de pagar?","r":"Te llega un correo con el botón “Entrar a Cupo”. Al publicar tu evento eliges usar tu evento Pro."}]}')),
('prod_cupo_paquete5', 'cupo-paquete-5', 'Cupo · Paquete 5 eventos Pro', 'Cinco eventos con todas las funciones de Cupo Pro para usar en 12 meses. Para negocios, comunidades y organizadores que repiten.', 79900, 1, 'Eventos', 31, '[]', '/assets/tienda/cupo.webp',
  json('{"acceso":{"app":"cupo","tipo":"paquete","unidades":5,"meses":12,"url":"https://os.vorka.mx/cupo/entrar/","boton":"Entrar a Cupo","detalle":"Pago único · 5 eventos Pro en 12 meses"},"titular":"Cinco eventos Pro para todo el año","subtitulo":"Todo lo de Cupo Pro en cinco eventos. Los aplicas cuando los necesites durante 12 meses.","incluye":[{"titulo":"5 eventos Pro","texto":"Cover, aprobación, preguntas, avisos, check-in con equipo y Excel en cada uno."},{"titulo":"Sin comisiones por boleto","texto":"El dinero del cover llega directo a ti."},{"titulo":"12 meses para usarlos","texto":"Ideal para eventos mensuales o temporadas."}],"para_quien":["Bares, cafés y espacios con eventos frecuentes","Comunidades de networking y emprendimiento","Organizadores de fiestas y talleres"]}'));
